# Digitalizacija beležk SHS in Kraljevine Jugoslavije - Diplomsko delo# Nik Česenj Vodovnik, 04180450 - Upravna informatika# Študijsko leto 2022/2023# Datoteka inner_folder.pyfrom .structure import Structureclass InnerFolder(Structure):    def __init__(self, name, path):        super().__init__(name, path)        self._num, self._meeting = self.parse_name()        self._files: list[object] = []        self._outter_folder: object = None    # PRINT OBJECT    def __str__(self):        return f"Ime mape:         {self._name}\n" \               f"Razpon sestankov: {self._num}\n" \               f"Vrsta sestanka:   {self._meeting}\n"    # PARSING METHOD    def parse_name(self) -> tuple[str, str]:        parsed = self.name.split("_")        return parsed[0], parsed[1]    @property    def num(self) -> str:        return self._num    @num.setter    def num(self, new_num: str) -> None:        self._num = new_num    @property    def meeting(self) -> str:        return self._meeting    @meeting.setter    def meeting(self, new_meeting):        self._meeting = new_meeting    @property    def files(self) -> list[object]:        return self._files    @files.setter    def files(self, new_list: list[object]) -> None:        self._files = new_list    def add_file(self, new_file: object):        self._files.append(new_file)    def add_files(self, new_files: list[object]) -> None:        self._files += new_files    @property    def outter_folder(self) -> object:        return self._outter_folder    @outter_folder.setter    def outter_folder(self, new_outter_folder: object) -> None:        self._outter_folder = new_outter_folder